from pathlib import Path
from html import escape
import json, textwrap, os
ROOT=Path('/mnt/data/LAWYGO_ATLAS_SITE')
AS=ROOT/'assets'; AS.mkdir(exist_ok=True)
for folder in ['journal','wiki','note','pro','litigation','pan','legal','previews']:(ROOT/folder).mkdir(exist_ok=True)
