def link(current,target):
 return os.path.relpath(ROOT/target, (ROOT/current).parent).replace('\\','/')
def A(current,target,label,cls=''):
 return f'<a class="{cls}" href="{link(current,target)}">{label}</a>'
def head(current,title,description,section):
 menu=''.join(A(current,p,n, 'active' if section==n else '') for n,p in nav)
 return f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{escape(description)}"><title>{escape(title)} | LAWYGO</title><link rel="stylesheet" href="{link(current,'assets/site.css')}"><script defer src="{link(current,'assets/site.js')}"></script></head><body data-page="{current}">
 <div class="utility"><div class="wrap utility-inner"><span>ECONOMY × LAW × INTELLIGENCE</span><span>대한민국 · 미국을 잇는 제도적 통찰</span><span class="utility-right">Independent Information Journal · Design Prototype</span></div></div>
 <header class="header"><div class="wrap header-main"><a href="{link(current,'index.html')}" class="logo" aria-label="LAWYGO 메인"><span class="logo-mark"><b>L</b><i></i></span><span class="logo-word">LAWYGO<span class="logo-sub">LEGAL INTELLIGENCE</span></span></a><nav class="desktop-nav">{menu}</nav><div class="header-actions">{A(current,'journal/newsletter.html','무료 뉴스레터','btn btn-outline btn-mini')}{A(current,'pricing.html','시작하기','btn btn-gold btn-mini')}<button class="menu-toggle" type="button" aria-label="메뉴 열기" aria-expanded="false">☰</button></div></div><div class="wrap mobile-nav" id="mobileNav">{menu}</div></header>'''
