 items=''.join(A(current,p,n) for n,p in [('서비스 소개','about.html'),('기술·특허','technology.html'),('콘텐츠 검증','methodology.html'),('출처','sources.html'),('문의','contact.html'),('개인정보','legal/privacy.html'),('이용약관','legal/terms.html')])
